test('vatSummary handles many invoices efficiently', () => {
  const invoices = [];
  for (let i = 0; i < 50; i++) {
    const inv = createInvoice({
      customerId: `C-${String((i % 10) + 1).padStart(3, '0')}`,
      issueDate: '2026-09-01',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'PRINT-A4', qty: 50 },
      ],
    }).value;
    const issued = issueInvoice(inv, invoices.map(i => i.number || '')).value;
    invoices.push(issued);
  }

  const r = vatSummary(invoices);
  assert.equal(r.length, 2);
  assert.ok(r[0].base > 0);
  assert.ok(r[0].vat > 0);
  assert.ok(r[1].base > 0);
  assert.ok(r[1].vat > 0);
