test('vatSummary does not mutate input invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const originalStatus = issued.status;
  const originalLines = issued.lines.length;

  const invoices = [issued];
  vatSummary(invoices);
  assert.equal(issued.status, originalStatus);
  assert.equal(issued.lines.length, originalLines);
});

